//! The Mastery EXP tab against the upstream page.
//!
//! `fixtures/cooking-mastery.json` is generated by
//! `script/cooking-mastery-oracle.mjs` from the upstream
//! `cooking-mastery-calc.html`, importing that repo's own save loader and
//! external systems. Every assertion here compares the Rust port with those
//! numbers, so a formula drift on either side fails loudly.

use idleon_cooking_mastery::{EXP_UPGRADES, Goal, Mastery, REQUIRED_LEVEL, UPGRADE_NAMES};
use idleon_import::import;
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/cooking-mastery.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("the oracle fixture is committed"))
        .expect("the oracle fixture is JSON")
}

fn number(value: &Value, key: &str) -> f64 {
    value[key]
        .as_f64()
        .unwrap_or_else(|| panic!("{key} is a number in the fixture"))
}

/// The imported fixture save and the oracle's expectations for it.
fn imported() -> (Mastery, Value) {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/data.json");
    let save = std::fs::read_to_string(path).expect("fixtures/data.json is committed");
    let imported = import(&save).expect("the fixture imports");
    let mastery = imported.mastery.expect("the fixture carries CookMaster");
    (mastery, fixture())
}

/// The oracle's number, within a relative tolerance so long products hold.
fn close(got: f64, expected: f64, what: &str) {
    let scale = expected.abs().max(1.0);
    assert!(
        (got - expected).abs() <= scale * 1e-9,
        "{what}: got {got}, upstream {expected}"
    );
}

#[test]
fn the_fixture_save_decodes_the_mastery_fields_upstream_reads() {
    let (mastery, oracle) = imported();
    close(
        mastery.level,
        number(&oracle, "masteryLevel"),
        "mastery level",
    );
    close(mastery.ladles, number(&oracle, "ladlesUsed"), "ladles used");
    close(
        mastery.cooking_levels,
        number(&oracle, "totalCookingLevel"),
        "total cooking level",
    );
    close(
        mastery.divorce_cake,
        number(&oracle, "meal73Level"),
        "Divorce Cake level",
    );
    close(
        mastery.ribbons,
        number(&oracle, "totalRibbonLevel"),
        "ribbon ranks",
    );
    close(
        mastery.points_spent(),
        number(&oracle, "pointsSpent"),
        "points spent",
    );
    close(
        mastery.points_available(),
        number(&oracle, "pointsAvailable"),
        "points available",
    );
    let per_lv = oracle["perLv"].as_array().expect("perLv is an array");
    for (index, expected) in per_lv.iter().enumerate() {
        close(
            mastery.per_lv(index),
            expected.as_f64().unwrap_or_default(),
            &format!("per level {index}"),
        );
    }
}

#[test]
